'use strict';
const BASE_V1={home,vision,architecture,ecosystem,productPage,platformPage,compositions,studio,workflows,agents,perspectives,essay,blockPage,hero,articleCards,render,footer,catalog};
const MEDIA='/assets/media/';
const picture=(name,alt,cls='')=>`<img class="${cls}" src="${MEDIA+name}.png" alt="${alt}" loading="lazy">`;
const frame=(content,cls='',id='')=>`<section ${id?`id="${id}"`:''} class="v2-section ${cls}"><div class="container">${content}</div></section>`;
function graphicMark(type='orb',color='currentColor'){
const b={orb:'<circle cx="100" cy="100" r="79" fill="none" stroke="currentColor" stroke-width="26"/><path d="M0 100h200M100 0v200" stroke="currentColor" stroke-width="2"/>',steps:'<path d="M15 185v-50h50V85h50V35h70v150Z" fill="currentColor"/>',cross:'<path d="M65 15h70v50h50v70h-50v50H65v-50H15V65h50Z" fill="currentColor"/>',arcs:'<path d="M20 185V105a80 80 0 0 1 160 0v80M55 185V105a45 45 0 0 1 90 0v80M90 185v-80a10 10 0 0 1 20 0v80" stroke="currentColor" stroke-width="17" fill="none"/>',grid:Array.from({length:16},(_,i)=>`<rect x="${15+i%4*45}" y="${15+Math.floor(i/4)*45}" width="34" height="34" fill="currentColor" opacity="${.25+(i%4)/4}"/>`).join(''),dots:Array.from({length:36},(_,i)=>`<circle cx="${18+i%6*33}" cy="${18+Math.floor(i/6)*33}" r="${4+i%6}" fill="currentColor"/>`).join('')};return `<svg class="graphic-mark" viewBox="0 0 200 200" aria-hidden="true" style="color:${color}">${b[type]||b.orb}</svg>`}
function signalSVG(){let strands='';for(let i=0;i<28;i++){let d=`M 0 ${180+(i-14)*3}`;for(let x=5;x<=430;x+=5){let y=180+Math.sin(x*(.08+i*.003)+i)*Math.max(0,110-x*.22)+Math.cos(x*.15+i)*24;d+=` L ${x} ${y.toFixed(2)}`}strands+=`<path class="noise-strand" d="${d}" fill="none" stroke="currentColor" stroke-width=".75" opacity=".3"/>`}return `<svg class="live-signal" viewBox="0 0 1000 360" role="img" aria-label="Linhas dispersas se organizam em um sinal contínuo"><g>${strands}</g><circle cx="535" cy="180" r="119" fill="#fdc234"/><rect class="signal-gate" x="495" y="60" width="115" height="240" fill="#734b9c"/><path class="signal-wave" d="M420 180C450 180 450 73 485 73S520 287 555 287 590 73 625 73 660 287 695 287 730 73 765 73 800 287 835 287 870 73 905 73 940 180 1000 180" fill="none" stroke="currentColor" stroke-width="3"/><g class="signal-particle" fill="#fdc234"><circle r="6"><animateMotion dur="6s" repeatCount="indefinite" path="M420 180C450 180 450 73 485 73S520 287 555 287 590 73 625 73 660 287 695 287 730 73 765 73 800 287 835 287 870 73 905 73 940 180 1000 180"/></circle></g><g stroke="currentColor" opacity=".15"><path d="M0 180h1000M250 0v360M500 0v360M750 0v360"/></g></svg>`}
function cubeV2(x,y,w,color){return `<path d="M${x} ${y}l${w} ${-w/2} ${w} ${w/2}v${w}l${-w} ${w/2} ${-w} ${-w/2}Z" fill="${color}"/><path d="M${x} ${y}l${w} ${w/2} ${w} ${-w/2}M${x+w} ${y+w/2}v${w}" fill="none" stroke="white" stroke-opacity=".7"/><path d="M${x+w} ${y+w/2}l${w} ${-w/2}v${w}l${-w} ${w/2}Z" fill="#1a1d23" opacity=".15"/>`}
let assemblyV2Id=0;function assemblySVG(){const uid='assembly-'+(++assemblyV2Id);return `<svg class="assembly-svg" viewBox="0 0 700 630" role="img" aria-label="Camadas modulares da arquitetura, separáveis pelo controle de composição"><defs><linearGradient id="${uid}-layer" x2="1" y2="1"><stop stop-color="#bfa6d5"/><stop offset="1" stop-color="#734b9c"/></linearGradient><radialGradient id="${uid}-sphere" cx=".3" cy=".2"><stop stop-color="#fff3bb"/><stop offset=".7" stop-color="#fdc234"/><stop offset="1" stop-color="#d99905"/></radialGradient></defs><g stroke="currentColor" opacity=".12" fill="none"><path d="M80 410L350 555 620 410 350 265Z M80 180L350 325 620 180 350 35Z M80 180v230M350 35v520M620 180v230"/><path d="M40 510L350 350 660 510M350 0v620" stroke-dasharray="3 7"/></g><g class="assembly-layer layer-0"><path d="M120 420L350 300 580 420 350 540Z" fill="#e5dfd7"/><path d="M120 420v18l230 120 230-120v-18L350 540Z" fill="#cdc6bd"/></g><g class="assembly-layer layer-1"><path d="M120 350L350 230 580 350 350 470Z" fill="#734b9c"/><path d="M120 350v22l230 120 230-120v-22L350 470Z" fill="#583279"/>${cubeV2(260,333,40,'#fdc234')}${cubeV2(390,330,25,'#ece6f1')}</g><g class="assembly-layer layer-2"><path d="M120 270L350 150 580 270 350 390Z" fill="#faf9f6" stroke="#d1c8d8"/><path d="M120 270v18l230 120 230-120v-18L350 390Z" fill="#e2dce7"/><g stroke="#734b9c" opacity=".6"><path d="M180 270l170 90 160-80M200 255l150 80 130-70M250 230l100 60 80-40"/></g></g><g class="assembly-layer layer-3"><path d="M120 180L350 60 580 180 350 300Z" fill="url(#${uid}-layer)"/><path d="M120 180v28l230 120 230-120v-28L350 300Z" fill="#734b9c"/><path d="M175 180l175 90 175-90-175-90Z M350 60v240M120 180h460" fill="none" stroke="#eee2f7" stroke-opacity=".45"/><circle class="assembly-sphere" cx="350" cy="143" r="42" fill="url(#${uid}-sphere)"/></g><g class="diagram-ticks" stroke="#734b9c"><path d="M580 180h80M580 270h80M580 350h80M120 420H40"/><circle cx="580" cy="180" r="3"/><circle cx="580" cy="270" r="3"/><circle cx="580" cy="350" r="3"/></g></svg>`}
function architectureModule(){return `<div class="architecture-lab" data-lab>${eyebrow('Architecture / composition study 01')}<div class="lab-grid"><div class="lab-art">${assemblySVG()}<span class="lab-coordinate">CAT / X 040 · Y 060 · Z <span id="lab-coordinate">65</span></span></div><div class="lab-copy"><h2>Uma base.<br>Muitas camadas<br>de possibilidade.</h2><p>Explore a estrutura. Cada capacidade tem seu papel; a composição conecta o trabalho.</p><div class="lab-tabs" role="tablist" aria-label="Camadas da composição">${['Identidade','Dados','Decisão','Experiência'].map((t,i)=>`<button role="tab" aria-selected="${i===0}" data-layer="${i}"><span>0${i+1}</span>${t}<b>↗</b></button>`).join('')}</div><p class="lab-description" id="lab-description">Quem participa, em qual organização e com quais permissões.</p><label class="explode-label">Compor <input type="range" min="0" max="100" value="65" id="explode-range" aria-label="Separar as camadas da composição"> Explodir</label>${link('/arquitetura/','Entre na arquitetura')}</div></div></div>`}
function kineticStrip(){return `<div class="kinetic-strip" aria-label="Organizar, compor, construir"><div aria-hidden="true">ORGANIZAR <i>●</i> COMPOR <i>↗</i> CONSTRUIR <i>●</i> ORGANIZAR <i>●</i> COMPOR <i>↗</i> CONSTRUIR <i>●</i></div></div>`}
function filmBlock(type='brand'){const banking=type==='banking',credit=type==='credit';const filename=banking?'banking-reel':credit?'credit-reel':'composition-film';const poster=banking?'/assets/screens/bank-desktop.jpg':credit?'/assets/screens/credit-queue.png':MEDIA+'ribbon.png';return `<figure class="film-block"><video controls playsinline preload="none" poster="${poster}" aria-label="${banking?'Sequência de telas de Banking Platform':credit?'Sequência de telas de Credit Platform':'Filme conceitual de composição Catalisa'}"><source src="${MEDIA+filename}.mp4" type="video/mp4"><p>Seu navegador não reproduz este vídeo. Explore as capturas na galeria de interfaces.</p></video><figcaption><span class="film-label">▶ ${type==='brand'?'MOTION STUDY / CATALISA':banking?'BANKING / INTERFACES':'CREDIT / INTERFACES'}</span><span>${type==='brand'?'Sequência conceitual de marca · sem áudio':'Montagem em movimento de capturas de referência · dados de exemplo · sem áudio'}</span></figcaption></figure>`}
function productShowcase(){return `<div class="product-showcase"><div class="showcase-nav" role="tablist" aria-label="Produtos em destaque"><button role="tab" aria-selected="true" data-showcase="banking">01 / Banking Platform</button><button role="tab" aria-selected="false" data-showcase="credit">02 / Credit Platform</button></div><div id="showcase-stage">${showcaseContent('banking')}</div></div>`}
function showcaseContent(slug){const bank=slug==='banking';return `<div class="showcase-frame appear"><div class="showcase-caption"><div>${eyebrow(bank?'Aplicativo / Desktop / Console':'Política / Mesa / Carteira')}<h3>${bank?'Uma base bancária.<br>Várias experiências.':'O processo de crédito<br>ganha estrutura.'}</h3></div>${link('/ecossistema/'+slug+'/','Explore o produto','button outline')}</div><div class="showcase-screens"><img class="showcase-desktop" src="/assets/screens/${bank?'bank-desktop.jpg':'credit-queue.png'}" alt="${bank?'Desktop Banking':'Fila da mesa Credit'} — captura de referência" loading="lazy">${bank?'<img class="showcase-mobile" src="/assets/screens/bank-mobile.png" alt="Aplicativo Banking — captura de referência" loading="lazy">':'<div class="showcase-stamp">PRODUTO<br>POLÍTICA<br>OPERAÇÃO<span>CCP / 02</span></div>'}</div><p class="small-note">Interfaces do material de referência. Dados de exemplo. Consulte o estágio e o contexto na página do produto.</p></div>`}
function posterCollection(){return `<div class="poster-collection"><a class="bauhaus-poster poster-purple" href="/capacidades/">${eyebrow('01 / Catálogo')}${graphicMark('arcs')}<h3>PEÇAS<br>COM<br>PROPÓSITO.</h3><span>Conheça as capacidades ↗</span></a><a class="bauhaus-poster poster-yellow" href="/composicoes/">${eyebrow('02 / Composição')}<h3>COMBINAR<br>MUDA<br>TUDO.</h3>${graphicMark('grid')}<span>Explore as combinações ↗</span></a><a class="bauhaus-poster poster-ink" href="/ecossistema/">${eyebrow('03 / Ecossistema')}${graphicMark('dots')}<h3>A BASE<br>GANHA<br>VIDA.</h3><span>Conheça os produtos ↗</span></a></div>`}
home=function(){return `<section class="home-hero-v2"><div class="hero-v2-copy">${eyebrow('CATALISA / INFRAESTRUTURA PARA CONSTRUIR')}<h1>Dê forma<br>ao que vem<br><em>depois.</em></h1><p>Uma plataforma de capacidades combináveis.<br>Da complexidade à construção.</p>${actions(link('/arquitetura/','Explore a arquitetura','button'),link('/ecossistema/','Conheça o ecossistema'))}<div class="hero-edition"><span>IDEIAS · DADOS · PROCESSOS · PESSOAS</span><span>EST. CATALISA ↗</span></div></div><div class="hero-v2-art">${picture('portal','Arco roxo escultural com círculo amarelo, escada laranja e abertura para o céu','hero-portal')}<div class="art-corner top">FORM / FUNCTION</div><div class="art-corner bottom">01 — POSSIBILIDADE EM CONSTRUÇÃO</div><div class="rotating-label" aria-hidden="true">✳</div></div></section>`+kineticStrip()+frame(`<div class="signal-heading"><div>${eyebrow('01 / DA COMPLEXIDADE À CLAREZA')}<h2>O ruído encontra<br><em>sentido.</em></h2></div><p>Dados, ferramentas e processos não precisam permanecer dispersos. A arquitetura dá uma linguagem comum ao que precisa trabalhar junto.</p></div><div class="signal-stage">${signalSVG()}<div class="signal-labels"><span>IDEIAS / ENTRADAS</span><span>CATALISA / COMPOSIÇÃO</span><span>ESTRUTURA / POSSIBILIDADES</span></div></div>`,'ink-section')+`<section class="citrus-section"><div class="citrus-copy">${eyebrow('02 / PENSAR EM CAPACIDADES')}<h2>O todo começa<br>pelas <em>partes.</em></h2><p>Uma agenda. Uma regra. Uma identidade. Um documento. Capacidades independentes que encontram novas formas de trabalhar juntas.</p>${link('/visao/','Conheça a visão')}<span class="oversized-asterisk" aria-hidden="true">✳</span></div><div class="citrus-art">${picture('citrus','Limão que se decompõe em pequenos cubos e se reorganiza em um bloco geométrico')}</div></section>`+frame(architectureModule(),'lab-section')+frame(`<div class="section-heading-v2">${eyebrow('04 / ARQUITETURA EM OPERAÇÃO')}<h2>A estrutura aparece<br>na experiência.</h2><p>App, desktop, backoffice e mesa. Banking e Credit mostram a plataforma por quem usa.</p></div>${productShowcase()}`,'showcase-section')+frame(`<div class="section-heading-v2 compact">${eyebrow('05 / EXPLORAR A BASE')}<h2>Construir é compor.</h2></div>${posterCollection()}`,'poster-section')+frame(`<div class="film-heading"><div>${eyebrow('06 / MOVIMENTO E TRANSFORMAÇÃO')}<h2>A próxima forma<br>está em movimento.</h2></div><p>Uma interpretação visual da ideia que conecta a marca: organizar, combinar e construir.</p></div>${filmBlock()}`,'film-section')+frame(`<div class="section-heading-v2">${eyebrow('07 / IDEIAS EM MOVIMENTO')}<h2>Perspectivas para<br>o que vem.</h2></div>${articleCards()}`,'editorial-section')};
vision=function(){return `<section class="manifesto-hero"><div class="container">${eyebrow('CATALISA / NOSSA VISÃO')}<h1>CONSTRUIR<br>É <span>COMPOR.</span></h1><div class="manifesto-bottom"><p>A complexidade não desaparece.<br>Ela encontra uma forma de trabalhar.</p>${graphicMark('cross')}</div></div></section>`+frame(`<div class="manifesto-editorial"><span class="vertical-label">DA INTENÇÃO À ESTRUTURA</span><h2>Uma boa base<br>abre espaço<br>para <em>o próximo.</em></h2><div><p>A complexidade de uma operação continua nos dados, nas regras, nas integrações e nas decisões que sustentam cada interação.</p><p>A Catalisa dá a essas responsabilidades uma forma que pode ser entendida, combinada e reutilizada.</p></div></div>`)+`<section class="ribbon-break">${picture('ribbon','Fios dispersos passam por um portal roxo e se transformam em uma fita amarela contínua')}<span class="image-caption">COMPLEXIDADE → ESTRUTURA → POSSIBILIDADE</span></section>`+frame(posterCollection())+frame(`<div class="grid2"><div>${eyebrow('DA ARQUITETURA AO PRODUTO')}<h2>As partes mudam.<br>A lógica permanece.</h2><p>Uma sala de vídeo participa de uma consulta, entrevista ou conversa jurídica. A capacidade permanece; o produto dá contexto à composição.</p>${link('/ecossistema/','Explore as expressões da base')}</div>${picture('citrus','Construção modular a partir de um limão','editorial-photo')}</div>`,'yellow-section')};
architecture=function(){return `<section class="architecture-hero-v2"><div class="container"><div class="arch-intro">${eyebrow('CATALISA / ARQUITETURA COMPOSABLE')}<h1>A estrutura<br>do <em>possível.</em></h1><p>Building blocks com responsabilidades próprias.<br>Uma linguagem comum para construir.</p></div>${assemblySVG()}<span class="architecture-caption">IDENTIDADE / DADOS / POLÍTICA / EXPERIÊNCIA</span></div></section>`+frame(architectureModule(),'lab-section')+frame(`<div class="responsibility-map"><div>${eyebrow('UM CONTRATO COMUM')}<h2>O que conecta<br>não precisa<br>se repetir.</h2></div><div class="domain-ledger">${[['01','Identidade','Usuário, organização e permissões.','iam'],['02','Dados','Fontes, documentos e informação.','data-store'],['03','Decisão','Políticas legíveis e versionadas.','decision-engine'],['04','Experiência','Canais, vídeo e jornadas.','rooms']].map(([n,t,d,s])=>`<a href="/capacidades/${s}/"><span>${n}</span><h3>${t}</h3><p>${d}</p><b>↗</b></a>`).join('')}</div></div>`)+frame(`<div class="split-statement"><div>${eyebrow('SEPARAÇÃO DE RESPONSABILIDADES')}<h2>A esteira busca.<br><em>O motor decide.</em></h2><p>Decision Platform reúne as fontes declaradas. Decision Engine avalia a política DMN publicada. A composição preserva o papel de cada capacidade.</p>${actions(link('/capacidades/decision-platform/','Veja a esteira'),link('/capacidades/decision-engine/','Veja o motor'))}</div><div class="diagram-theater">${signalSVG()}</div></div>`,'yellow-section')+frame(head('CONTRATOS E ESTÁGIOS','Uma arquitetura<br>declara seus limites.')+rows([['Produção, Beta e Alpha','A documentação diferencia o estágio de cada capacidade.'],['Responsabilidades próprias','Quem guarda um arquivo, quem avalia uma regra e quem entrega um evento continuam sendo papéis distintos.'],['Uma base compartilhada','Identidade, permissões e isolamento formam uma linguagem comum.']])+source('https://docs.catalisa.app/blocks/'))};
articleCards=function(){return `<div class="editorial-cards">${ESSAYS.map((e,i)=>`<a class="editorial-card editorial-card-${i}" href="/perspectivas/${e.slug}/"><div class="editorial-image">${picture(['portal','citrus','ribbon'][i],e.title)}<span>0${i+1} ↗</span></div>${eyebrow(e.tag)}<h3>${e.title}</h3><p>${e.desc}</p><span class="text-link">Ler perspectiva ↗</span></a>`).join('')}</div>`};
perspectives=function(){return `<section class="editorial-hero"><div class="container">${eyebrow('CATALISA / PERSPECTIVAS')}<div class="editorial-headline"><h1>IDEIAS EM<br><em>MOVIMENTO.</em></h1>${graphicMark('orb')}</div><p>Arquitetura, composição e responsabilidade.<br>O que pensamos também toma forma no que construímos.</p></div></section>`+frame(articleCards())+frame(`<div class="grid2">${picture('ribbon','Da complexidade a uma composição clara','editorial-photo')}<div>${eyebrow('ACERVO / INSIGHTS')}<h2>O contexto também<br>faz parte da base.</h2><p>O site atual reúne análises sobre IA, interfaces conversacionais e operações em diferentes mercados.</p>${link('https://catalisa.io/insights/','Explore o acervo oficial')}</div></div>`,'yellow-section')};
ecosystem=function(){return `<section class="ecosystem-hero-v2"><div class="container">${eyebrow('CATALISA / ECOSSISTEMA')}<h1>UMA BASE.<br><em>MUITAS VIDAS.</em></h1><div class="ecosystem-hero-bottom"><p>Produtos que aplicam capacidades compartilhadas<br>a contextos específicos.</p>${graphicMark('arcs')}</div></div></section>`+frame(`<div class="ecosystem-index">${PRODUCTS.map((p,i)=>`<a class="ecosystem-entry ecosystem-entry-${i}" href="/ecossistema/${p.slug}/"><span class="product-index">0${i+1}</span><div><div class="eyebrow">${p.category}</div><h2>${p.name}</h2><p>${p.description}</p><span class="text-link">Explore a composição ↗</span></div><div class="product-art-v2">${i===0?'<img src="/assets/screens/bank-desktop.jpg" alt="Interface de referência Banking" loading="lazy">':i===1?'<img src="/assets/screens/credit-queue.png" alt="Interface de referência Credit" loading="lazy">':i===2?picture('portal','Arquitetura e possibilidades'):i===3?graphicMark('arcs'):i===4?graphicMark('steps'):i===5?graphicMark('orb'):graphicMark('grid')}</div></a>`).join('')}</div>`)+frame(`<div class="grid2"><div><h2>A capacidade permanece.<br>O contexto transforma.</h2><p>Uma identidade, uma agenda, uma assinatura. A mesma peça pode participar de uma nova experiência sem perder sua responsabilidade.</p>${link('/composicoes/','Explore a composição')}</div>${picture('citrus','Um todo se revela em capacidades independentes','editorial-photo')}</div>`,'yellow-section')};
hero=function(tag,title,desc,visual=''){let panel='',variant='';if(visual==='signal'){panel=signalSVG();variant='variant-yellow'}else if(visual==='plane'){panel=picture('portal','Arquitetura que abre novas possibilidades','hero-photo')}else if(visual==='orbit'){panel=`<div class="hero-mark-panel">${graphicMark('orb')}</div>`}else if(visual==='document'){panel=`<div class="hero-mark-panel">${graphicMark('arcs')}</div>`}else if(visual==='modules'){panel=picture('citrus','Um todo que se revela em capacidades','hero-photo');variant='variant-yellow'}else if(visual==='stack'){panel=assemblySVG();variant='variant-purple'}else if(visual){panel=art(visual,'hero-art')}return `<section class="hero-alt-v2 ${variant}"><div class="container">${panel?`<div class="hero-split"><div>${eyebrow(tag)}<h1>${title}</h1><p class="lead">${desc}</p></div><div>${panel}</div></div>`:`${eyebrow(tag)}<h1>${title}</h1><p class="lead">${desc}</p>`}</div></section>`};
platformPage=function(p){const bank=p.slug==='banking';return `<section class="platform-hero ${bank?'platform-banking':'platform-credit'}"><div class="container">${eyebrow('CATALISA / '+p.name.toUpperCase())}<div class="platform-headline"><h1>${bank?'O BANCO<br>EM <em>CONTEXTO.</em>':'CRÉDITO<br>EM <em>CAMADAS.</em>'}</h1><div>${graphicMark(bank?'arcs':'steps')}<p>${p.description}</p></div></div><div class="platform-hero-links">${link('#produto-filme','Ver interfaces em movimento','button outline')}${link('#jornada','Explore a jornada','text-link')}</div></div></section>`+frame(`<div class="product-wide-screen"><img src="/assets/screens/${bank?'bank-desktop.jpg':'credit-queue.png'}" alt="${p.name} — captura da interface de referência" fetchpriority="high">${bank?'<img class="phone-over" src="/assets/screens/bank-mobile.png" alt="App Banking — captura em aparelho">':''}</div><p class="small-note">Material de referência. Dados de exemplo; a disponibilidade depende da frente e do ambiente.</p>`,'product-screen-section')+frame(`<div class="platform-principle"><div class="principle-index">${bank?'01':'02'}</div><h2>${p.principle}</h2><p>${p.principleText}</p></div>`)+frame(`<div class="film-heading"><div>${eyebrow('DO PRODUTO À TELA')}<h2>${bank?'App. Desktop.<br>Backoffice.':'Política. Mesa.<br>Operação. Carteira.'}</h2></div><p>Uma sequência de capturas reais do material de referência. Use os controles para assistir ou pausar.</p></div>${filmBlock(p.slug)}`,'ink-section','produto-filme')+frame(`<div class="journey-intro">${eyebrow('A JORNADA / '+p.name.toUpperCase())}<h2>Um processo.<br>Próximos estados.</h2></div><div class="journey-board">${p.steps.map(([t,d],i)=>`<div class="journey-panel"><span class="journey-n">0${i+1}</span>${graphicMark(['orb','grid','steps','cross'][i])}<h3>${t}</h3><p>${d}</p></div>`).join('')}</div>`,'','jornada')+frame(`<div class="section-heading-v2">${eyebrow('O PRODUTO VISTO POR DENTRO')}<h2>As telas têm<br>contexto.</h2><p>Clique para ampliar e consultar a legenda de cada captura.</p></div>${gallery(p.slug)}`,'gallery-section-v2')+frame(head('CAPACIDADES RELACIONADAS','O que ajuda a entender<br>a composição.')+`<div class="grid3">${p.blocks.map(s=>BLOCKS.find(b=>b.slug===s)).filter(Boolean).map(blockTile).join('')}</div><p class="small-note">Seleção conceitual de capacidades. Os contratos e estágios específicos permanecem na documentação.</p>`)+frame(`<div class="editorial"><h2>O estágio também<br>faz parte da história.</h2><p>${p.boundary}</p></div>${source(p.source,'Documentação do repositório indicado pelo usuário')}`)};
productPage=function(p){if(['banking','credit'].includes(p.slug))return platformPage(p);if(p.slug==='decision')return decisionExperience(p);if(p.slug==='recrutamento')return recruitmentExperience(p);if(p.slug==='med')return medExperience(p);if(p.slug==='juridico')return legalExperience(p);return biometricExperience(p)};
function productClose(p){return frame(`<div class="product-boundary"><div>${eyebrow('RESPONSABILIDADE E ESCOPO')}<h2>Uma experiência.<br>Limites explícitos.</h2><p>${p.boundary}</p></div><div>${source(p.source,'Resumo baseado no site oficial do produto')}${link(p.source,'Explore o produto oficial','button outline')}</div></div>`)+frame(`<div class="section-heading-v2">${eyebrow('POR TRÁS DA EXPERIÊNCIA')}<h2>Capacidades relacionadas.</h2></div><div class="grid3">${p.blocks.slice(0,3).map(s=>BLOCKS.find(b=>b.slug===s)).filter(Boolean).map(blockTile).join('')}</div><p class="small-note">Composição conceitual. Consulte os contratos e os estágios das capacidades.</p>`)}
function medExperience(p){return `<section class="med-cover"><div class="container"><div>${eyebrow('CATALISA / MED')}<h1>O cuidado<br>tem um lado<br><em>humano.</em></h1><p>${p.description}</p>${link(p.source,'Conheça Med','button outline')}</div><div class="med-cover-art">${graphicMark('arcs')}<div class="appointment-note"><span>JORNADA / CONSULTA</span><b>Conversa.<br>Agenda.<br>Encontro.</b><i>O registro espera a pessoa.</i></div></div></div></section>`+frame(`<div class="section-heading-v2">${eyebrow('A FRONTEIRA DO PRODUTO')}<h2>Entre o rascunho e o registro,<br>existe uma pessoa.</h2></div><div class="document-comparison"><div class="document-comparison-copy"><span>01 / A IA PREPARA</span><h3>Rascunho.</h3><p>A transcrição organiza o encontro. O texto ainda aguarda revisão e liberação.</p><div class="draft-lines"><i></i><i></i><i></i><i></i></div><em>Aguardando revisão</em></div><div class="document-comparison-copy signed"><span>02 / O PROFISSIONAL LIBERA</span><h3>Registro.</h3><p>Quem atendeu revisa, ajusta e libera. A responsabilidade permanece explícita.</p><div class="draft-lines"><i></i><i></i><i></i><i></i></div><em>Revisado pelo profissional ✓</em></div></div>`)+frame(`<div class="section-heading-v2">${eyebrow('DA CONVERSA À CONSULTA')}<h2>Uma jornada que<br>não perde o contexto.</h2></div><div class="appointment-timeline">${p.steps.map(([t,d],i)=>`<div><span>0${i+1}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div>`,'yellow-section')+productClose(p)}
function legalExperience(p){return `<section class="legal-cover"><div class="container">${eyebrow('CATALISA / JURÍDICO')}<h1>O CONHECIMENTO<br>DA <em>CASA.</em></h1><div class="legal-bottom"><p>${p.description}</p><div class="legal-books">${[0,1,2,3,4].map((n)=>`<div style="--book:${n}"><span>${['POLÍTICAS','TESES','PEÇAS','HISTÓRICO','CONTEXTO'][n]}</span></div>`).join('')}</div></div></div></section>`+frame(`<div class="legal-manifesto"><span>ACERVO / RESPOSTA / RESPONSABILIDADE</span><h2>Responder com contexto.<br>Analisar com<br><em>responsabilidade.</em></h2><p>${p.principleText}</p></div>`)+frame(`<div class="section-heading-v2">${eyebrow('A JORNADA DO CASO')}<h2>O atendimento encontra<br>o repertório do escritório.</h2></div><div class="legal-index">${p.steps.map(([t,d],i)=>`<div><span>0${i+1}</span><h3>${t}</h3><p>${d}</p><b>↘</b></div>`).join('')}</div>`,'ink-section')+productClose(p)}
function recruitmentExperience(p){return `<section class="recruit-cover"><div class="container">${eyebrow('CATALISA / RECRUTAMENTO')}<h1>CONVERSA.<br>ENCONTRO.<br><em>PARECER.</em></h1><div class="recruit-bottom"><p>${p.description}</p><div class="recruit-glyphs">${graphicMark('orb')}${graphicMark('steps')}${graphicMark('cross')}</div></div></div></section>`+frame(`<div class="section-heading-v2">${eyebrow('UMA JORNADA / VÁRIAS PESSOAS')}<h2>Candidato, cliente<br>e consultor.</h2></div><div class="recruit-lanes">${[['Candidato','Etapa, status e agenda da entrevista.'],['Empresa cliente','Andamento da vaga e envio de currículo.'],['Consultor','Processo, registro e aprovação do parecer.']].map(([t,d],i)=>`<div><span>0${i+1}</span><h3>${t}</h3><p>${d}</p><div class="lane-line"><i></i><i></i><i></i></div></div>`).join('')}</div>`)+frame(`<div class="journey-board">${p.steps.map(([t,d],i)=>`<div class="journey-panel"><span class="journey-n">0${i+1}</span>${graphicMark(['dots','orb','arcs','grid'][i])}<h3>${t}</h3><p>${d}</p></div>`).join('')}</div>`,'yellow-section')+frame(`<div class="recruit-quote"><h2>O parecer nasce<br>como rascunho.<br><em>A publicação tem autor.</em></h2><p>${p.principleText}</p></div>`,'ink-section')+productClose(p)}
function decisionExperience(p){return `<section class="decision-cover"><div class="container">${eyebrow('CATALISA / DECISION')}<div class="decision-cover-grid"><div><h1>A REGRA<br>TEM <em>VERSÃO.</em></h1><p>${p.description}</p>${link(p.source,'Explore Decision','button outline')}</div><div class="decision-grid-art">${graphicMark('grid')}<span>POLÍTICA<br>EXECUÇÃO<br>EVIDÊNCIA</span></div></div></div></section>`+frame(`<div class="rule-lab" data-rule-lab><div>${eyebrow('EXEMPLO INTERATIVO / ILUSTRATIVO')}<h2>Uma regra que<br>você consegue ler.</h2><p>Altere a entrada para observar o caminho. Este exemplo visual usa uma regra simplificada criada para explicar o conceito; não é a política do produto.</p><label>Entrada do exemplo <strong id="demo-score-value">650</strong><input type="range" min="400" max="900" value="650" id="demo-score"></label><p class="small-note">Regra ilustrativa: entrada ≥ 700 segue pelo caminho A; demais entradas seguem pelo caminho B.</p></div><div class="rule-result"><div class="rule-path"><span>ENTRADA</span><b id="demo-input">650</b><i>↓</i><span>REGRA / ≥ 700</span><i>↓</i><strong id="demo-outcome">CAMINHO B</strong></div><div class="rule-receipt"><span>VERSÃO DO EXEMPLO / 1.0</span><span id="demo-reason">650 é menor que 700.</span></div></div></div>`)+frame(`<div class="decision-responsibilities"><div>${eyebrow('01 / FONTES')}<h2>A esteira<br><em>busca.</em></h2><p>Decision Platform reúne dados das fontes declaradas.</p>${link('/capacidades/decision-platform/','Conheça a esteira')}</div><div>${eyebrow('02 / POLÍTICA')}<h2>O motor<br><em>decide.</em></h2><p>Decision Engine avalia a tabela DMN publicada.</p>${link('/capacidades/decision-engine/','Conheça o motor')}</div></div>`,'yellow-section')+productClose(p)}
function biometricExperience(p){return `<section class="bio-cover"><div class="container"><div>${eyebrow('CATALISA / BIOMETRICS')}<h1>A IDENTIDADE<br>ENCONTRA<br><em>EVIDÊNCIA.</em></h1><p>${p.description}</p></div><div class="bio-face">${art('biometrics','bio-sculpture')}<div class="scan-line"></div><span class="bio-corner c1"></span><span class="bio-corner c2"></span><span class="bio-corner c3"></span><span class="bio-corner c4"></span><span class="bio-label">CAPTURA / POLÍTICA / RESULTADO</span></div></div></section>`+frame(`<div class="bio-journey">${p.steps.map(([t,d],i)=>`<div><span class="bio-dot">0${i+1}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div>`)+frame(`<div class="grid2"><div>${eyebrow('A DECISÃO TEM CONTEXTO')}<h2>Um resultado.<br>O caminho<br>até ele.</h2><p>${p.principleText}</p></div><div class="evidence-poster"><span>VERIFICAÇÕES</span><span>LIMIARES</span><span>MODELO</span><span>ASSINATURA</span>${graphicMark('orb')}</div></div>`,'ink-section')+productClose(p)}
compositions=function(){return hero('CATALISA / COMPOSIÇÕES','A combinação<br>muda <em>o resultado.</em>','Explore exemplos de jornadas com capacidades reais. Os diagramas são ilustrativos; os contratos e estágios estão nas páginas dos blocos.','modules')+frame(composition())+frame(architectureModule(),'lab-section')+frame(posterCollection())};
blockPage=function(b){let html=BASE_V1.blockPage(b);const old=art(b.art);let visual;if(b.category==='Decisão')visual=`<div class="catalog-domain-glyph">${graphicMark('grid')}</div>`;else if(b.category==='Financeiro')visual=`<div class="catalog-domain-glyph finance">${graphicMark('steps')}</div>`;else if(b.category==='Dados'||b.category==='Inteligência')visual=`<div class="catalog-domain-glyph data">${graphicMark('dots')}</div>`;else if(b.category==='Identidade')visual=`<div class="catalog-domain-glyph">${graphicMark('orb')}</div>`;else if(b.category==='Comunicação')visual=`<div class="catalog-domain-glyph data">${graphicMark('arcs')}</div>`;else visual=assemblySVG();return html.replace(old,visual)};
function bindExperienceV2(){document.body.dataset.page=ROUTE.split('/')[1]||'home';document.body.classList.add('experience-v2');const media=window.matchMedia('(prefers-reduced-motion: reduce)');let paused=media.matches;let control=$('#motion-control');if(!control){control=document.createElement('button');control.id='motion-control';control.className='motion-controls';control.setAttribute('aria-label','Pausar animações');document.body.append(control)}const applyPause=()=>{document.body.classList.toggle('motion-paused',paused);control.textContent=paused?'▶ Ativar movimento':'Ⅱ Pausar movimento';control.setAttribute('aria-pressed',paused);document.querySelectorAll('svg animateMotion').forEach(el=>{const svg=el.ownerSVGElement;if(paused)svg.pauseAnimations?.();else svg.unpauseAnimations?.()})};control.onclick=()=>{paused=!paused;applyPause()};applyPause();const lab=$('[data-lab]');if(lab){const r=$('#explode-range');const set=()=>{lab.style.setProperty('--explode',r.value/100);$('#lab-coordinate').textContent=r.value};r.addEventListener('input',set);set();const desc=['Quem participa, em qual organização e com quais permissões.','Fontes e documentos organizados com responsabilidades próprias.','Políticas versionadas para tornar a resposta legível.','Canais e interfaces dão contexto às capacidades.'];$$('[data-layer]').forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.layer);$$('[data-layer]').forEach(x=>x.setAttribute('aria-selected',x===b));$('#lab-description').textContent=desc[n];$$('.assembly-layer',lab).forEach((x,i)=>x.style.opacity=i===3-n?'1':'.38')}))}$$('[data-showcase]').forEach(b=>b.addEventListener('click',()=>{$$('[data-showcase]').forEach(x=>x.setAttribute('aria-selected',x===b));$('#showcase-stage').innerHTML=showcaseContent(b.dataset.showcase)}));if($('#demo-score')){const score=$('#demo-score');const update=()=>{const n=Number(score.value),yes=n>=700;$('#demo-score-value').textContent=n;$('#demo-input').textContent=n;$('#demo-outcome').textContent=yes?'CAMINHO A':'CAMINHO B';$('#demo-reason').textContent=n+(yes?' é maior ou igual a 700.':' é menor que 700.');$('.rule-result').classList.toggle('path-a',yes)};score.addEventListener('input',update);update()}if(media.matches){$$('video').forEach(v=>v.autoplay=false)}document.addEventListener('visibilitychange',()=>{if(document.hidden)$$('video').forEach(v=>v.pause())})}
catalog=function(){let content=BASE_V1.catalog();const end=content.indexOf('</section>')+10;const newHero=`<section class="catalog-cover"><div class="container"><div>${eyebrow('CATALISA / CATÁLOGO DE CAPACIDADES')}<h1>PEÇAS COM<br><em>PROPÓSITO.</em></h1><p>Encontre a capacidade, entenda o contrato e confira o estágio. Uma base com responsabilidades que você consegue ler.</p></div><div class="catalog-counter"><strong>${BLOCKS.length}</strong><span>BUILDING BLOCKS<br>CATÁLOGO TÉCNICO PÚBLICO</span>${graphicMark('cross')}</div></div></section>`;return newHero+content.slice(end)};

